package my.waqt.app;import android.content.*;public class AlarmReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if("my.waqt.TEST".equals(i.getAction())){long delay=System.currentTimeMillis()-i.getLongExtra("at",0);if(delay>=-1000&&delay<120000)try{c.startForegroundService(new Intent(c,AzanService.class).putExtra("prayer","Ujian Azan"));}catch(Exception ignored){}return;}boolean valid=Alarms.valid(c,i);Alarms.arm(c);if(valid)try{c.startForegroundService(new Intent(c,AzanService.class).putExtra("prayer",i.getStringExtra("prayer")));}catch(Exception ignored){}}}